<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { OrderAction, OrderStatus, type CourierOption, type OrderSummary } from '@express-platform/shared-types';
import { adminApi } from '../services/api';
import { adminAuth } from '../stores/auth';
import { errorMessage, formatTime, money, statusLabel } from '../utils';

const router = useRouter(); const orders = ref<OrderSummary[]>([]); const couriers = ref<CourierOption[]>([]); const loading = ref(true); const error = ref('');
const filter = ref<'ALL'|OrderStatus>('ALL'); const dispatching = ref(false); const selected = ref<OrderSummary|null>(null); const courierId = ref(''); const dispatchError = ref('');
const canDispatch = computed(() => adminAuth.state.subject?.permissions.includes('orders.dispatch') ?? false);
const filtered = computed(() => filter.value==='ALL' ? orders.value : orders.value.filter((order)=>order.status===filter.value));
onMounted(() => void load());
async function load(): Promise<void> { loading.value=true; error.value=''; try { [orders.value,couriers.value]=await Promise.all([adminApi.orders(),adminApi.couriers()]); } catch(cause:unknown){error.value=errorMessage(cause);} finally{loading.value=false;} }
function openDispatch(order:OrderSummary):void { selected.value=order; courierId.value=couriers.value[0]?.id??''; dispatchError.value=''; }
async function dispatch():Promise<void> { if(!selected.value||!courierId.value||dispatching.value)return; dispatching.value=true; dispatchError.value=''; try { await adminApi.act(selected.value.id,{action:OrderAction.DISPATCH,courierId:courierId.value,reason:'管理员从运营中心人工调度'}); selected.value=null; await load(); } catch(cause:unknown){dispatchError.value=errorMessage(cause);} finally{dispatching.value=false;} }
</script>
<template>
  <div><div class="page-head"><div><h1 class="page-title">订单调度</h1><p class="page-subtitle">人工分配配送员，后端 RBAC 与状态机双重校验</p></div><div class="head-actions"><span class="mock-pill">● MockLogisticsProvider</span><button class="secondary" @click="load">刷新</button></div></div>
    <div class="filters"><button v-for="option in [{v:'ALL',n:'全部'},{v:OrderStatus.PENDING_DISPATCH,n:'待调度'},{v:OrderStatus.PENDING_ACCEPTANCE,n:'待接单'},{v:OrderStatus.IN_TRANSIT,n:'配送中'},{v:OrderStatus.COMPLETED,n:'已完成'}]" :key="option.v" :class="{active:filter===option.v}" @click="filter=option.v as typeof filter">{{ option.n }}</button></div>
    <div v-if="loading" class="panel state"><strong>正在加载订单</strong>同步订单、配送员与权限信息…</div>
    <div v-else-if="error" class="panel state error"><strong>列表加载失败</strong>{{ error }}<br/><button class="secondary" @click="load">重试</button></div>
    <div v-else-if="filtered.length===0" class="panel state"><strong>当前筛选下没有订单</strong>新订单将自动出现在此列表。</div>
    <div v-else class="panel table-wrap"><table class="data-table"><thead><tr><th>订单</th><th>服务</th><th>状态</th><th>费用</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="order in filtered" :key="order.id" @click="router.push(`/orders/${order.id}`)"><td><strong>{{ order.orderNo }}</strong><small>{{ order.shipment?.shipmentNo??'待生成运单' }}</small></td><td>{{ order.serviceType }}</td><td><span class="status">{{ statusLabel[order.status] }}</span></td><td>{{ money(order.estimatedFee,order.currency) }}</td><td>{{ formatTime(order.createdAt) }}</td><td><button v-if="order.status===OrderStatus.PENDING_DISPATCH&&canDispatch" class="dispatch-button" @click.stop="openDispatch(order)">分配配送员</button><span v-else-if="order.status===OrderStatus.PENDING_DISPATCH" class="no-permission">无调度权限</span><button v-else class="detail-button" @click.stop="router.push(`/orders/${order.id}`)">查看详情</button></td></tr></tbody></table></div>
    <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="dispatch-modal panel"><div class="modal-head"><div><span>MANUAL DISPATCH</span><h2>分配配送员</h2></div><button @click="selected=null">×</button></div><div class="order-chip"><small>待调度订单</small><strong>{{ selected.orderNo }}</strong></div><label>选择配送员<select v-model="courierId"><option value="" disabled>请选择</option><option v-for="courier in couriers" :key="courier.id" :value="courier.id">{{ courier.displayName }} · {{ courier.phone }} · 在途 {{ courier.activeOrderCount }}</option></select></label><div v-if="couriers.length===0" class="empty-courier">暂无可用配送员，无法执行调度。</div><div v-if="dispatchError" class="dispatch-error">{{ dispatchError }}</div><div class="modal-actions"><button class="secondary" @click="selected=null">取消</button><button class="primary" :disabled="dispatching||!courierId" @click="dispatch">{{ dispatching?'正在调度…':'确认分配' }}</button></div><p>确认后真实调用订单动作接口，生成 Mock 运单并进入“待接单”。</p></section></div>
  </div>
</template>
<style scoped>
.head-actions { display:flex; align-items:center; gap:12px; }.filters { display:flex; gap:8px; margin-bottom:18px; }.filters button { padding:9px 15px; color:#786f67; border:1px solid #e5dbd2; border-radius:999px; background:#fffdfa; font-size:12px; }.filters button.active { color:#fff; border-color:#2f2a26; background:#2f2a26; font-weight:800; }.data-table td strong,.data-table td small { display:block; }.data-table td small { margin-top:5px; color:#948a81; font-size:10px; }.dispatch-button,.detail-button { padding:7px 11px; border-radius:9px; font-size:11px; font-weight:800; }.dispatch-button { color:#fff; border:0; background:#e7642e; }.detail-button { color:#665d55; border:1px solid #e3d9d0; background:#fff; }.no-permission { color:#a13e32; font-size:11px; }.modal-backdrop { position:fixed; inset:0; z-index:20; display:grid; place-items:center; background:rgba(31,27,24,.48); backdrop-filter:blur(4px); }.dispatch-modal { width:480px; padding:28px; }.modal-head { display:flex; justify-content:space-between; }.modal-head span { color:#dc612d; font-size:9px; letter-spacing:2px; font-weight:900; }.modal-head h2 { margin:7px 0 0; font-size:24px; }.modal-head button { align-self:flex-start; color:#8b8178; border:0; background:transparent; font-size:26px; }.order-chip { margin:24px 0; padding:17px; border-radius:13px; background:#f6f1eb; }.order-chip small,.order-chip strong { display:block; }.order-chip small { color:#8d837a; font-size:10px; }.order-chip strong { margin-top:6px; font-size:14px; }.dispatch-modal label { display:block; color:#6c635b; font-size:12px; font-weight:800; }.dispatch-modal select { width:100%; height:46px; margin-top:9px; padding:0 12px; border:1px solid #e4dad1; border-radius:11px; background:#fff; }.dispatch-error,.empty-courier { margin-top:16px; padding:12px; border-radius:10px; color:#a13e32; background:#fff1ee; font-size:12px; }.modal-actions { display:flex; justify-content:flex-end; gap:10px; margin-top:24px; }.dispatch-modal>p { margin:16px 0 0; color:#978d84; font-size:10px; line-height:1.5; }
</style>
